Использую nextjs 15, соответственно компонент должен рендериться на сервере. На всякий случай перед рендером проверяю существует ли переменная. Контроллер считает, что она есть. То что внутри DivKit так не думает(((

```
import React from "react";
// @ts-expect-error I can't do anything
import { GlobalVariablesController } from "@divkitframework/divkit/typings/variables";
import {
    createGlobalVariablesController,
    createVariable
} from "@divkitframework/divkit/client-hydratable";
// @ts-expect-error I can't do anything
import {DivKit, DivKitProps} from "@divkitframework/react";
import "@divkitframework/divkit/dist/client.css";

export default function MyDivKit( { json }: {json: DivKitProps.json}) {
    const varController: GlobalVariablesController = createGlobalVariablesController();
    const themeVar = createVariable<'string'>('theme', 'string', 'dark');
    varController.setVariable(themeVar);

    if (varController.getVariable('theme')) {
        return (
            <DivKit globalVariablesController={varController}
                            json={{
                                "card": {
                                    "log_id": "div2_sample_card",
                                    "states": [
                                        {
                                            "state_id": 0,
                                            "div": {
                                                "type": "text",
                                                "text": "@{theme}",
                                                "font_size": 20,
                                            }
                                        }
                                    ]
                                },
                            }} id="app">
            </DivKit>
        );
    }
    else
        return <></>
}
```

