object DivkitIntegration {
    val gson = Gson()

    fun divConfiguration(context: Context, activity: Activity): DivConfiguration.Builder {
        return DivConfiguration.Builder(ImageLoader(context))
            .enableVisibilityBeacons()
            .enableLongtapActionsPassingToChild()
            .tooltipRestrictor { _, _ -> true }
            .divDownloader(DemoDivDownloader())
            .supportHyphenation(true)
